def rect(s,x,y,w,h,color):
 sh=s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE,PI(x),PI(y),PI(w),PI(h));sh.fill.solid();sh.fill.fore_color.rgb=PC.from_string(color);sh.line.fill.background();return sh
def text(s,x,y,w,h,txt,size=22,color=FG,bold=False):
 tf=s.shapes.add_textbox(PI(x),PI(y),PI(w),PI(h)).text_frame;tf.word_wrap=True
 for i,line in enumerate(txt.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.font.name='Aptos';p.font.size=PP(size);p.font.bold=bold;p.font.color.rgb=PC.from_string(color);p.space_after=PP(13)
 return tf
for n,(title,sub,items,secs,notes) in enumerate(slides):
 s=prs.slides.add_slide(prs.slide_layouts[6]);s.background.fill.solid();s.background.fill.fore_color.rgb=PC.from_string(BG)
 text(s,.6,.35,11,.35,'CDS528   /   FLIGHT DELAY INSURANCE',12,TEAL,True)
 text(s,.6,.95,12.1,1.05,title,31,FG,True)
 text(s,.6,2.05,12,.7,sub,19,MUTED)
 if n==2:
  for j,(label,body) in enumerate([('CAPITAL','LP → InsurancePool'),('POLICY','Traveller → Insurance → NFT'),('OUTCOME','Reporter → Oracle → settlement')]):
   rect(s,.6+j*4.1,3.05,3.9,1.1,'173039');text(s,.8+j*4.1,3.2,3.5,.3,label,13,TEAL,True);text(s,.8+j*4.1,3.63,3.5,.4,body,16)
  text(s,.65,4.65,11.9,1.7,'\n'.join(items),19)
 elif n==5:
  for j,(num,lab) in enumerate([('2,000','Initial capital'),('1,030','After settlements'),('2,030','After new deposit')]):
   rect(s,.6+j*4.1,3.05,3.9,1.45,'173039');text(s,.85+j*4.1,3.2,3.4,.6,num,34,TEAL,True);text(s,.85+j*4.1,3.9,3.4,.4,lab,16,MUTED)
  text(s,.65,4.85,12,1.7,'\n'.join(items),20)
 else:
  for j,item in enumerate(items):
   y=3.1+j*.95;rect(s,.6,y,.08,.55,TEAL);text(s,.95,y,11.7,.85,item,22)
 text(s,.6,7.05,10,.25,'MOCK ASSETS ONLY  |  Sources and evidence: accompanying report',10,MUTED)
 text(s,11.8,7.05,1,.25,f'{n+1:02d} / {len(slides):02d}',10,MUTED)
 s.notes_slide.notes_text_frame.text=f'Target: {secs} seconds.\n\n'+notes
prs.save(OUT/'CDS528_Presentation.pptx')
notes=['# CDS528 Presentation Script','Main slides: 12 minutes; appendix excluded. Q&A: 3 minutes.','Assign actual speakers before rehearsal. For four speakers, suggested split: slides 1–3 / 4–6 / 7–9 / 10–12. For 3 or 5 members, redistribute so everybody speaks.']
for i,(title,sub,items,secs,script) in enumerate(slides):notes+= [f'## Slide {i+1}: {title} ({secs}s)',script]
notes+=['# Q&A preparation','Q: Does the system know whether a flight really departed?\nA: No. Time phases use scheduled departure; delay reports are authorised manual input.','Q: Can LPs lose money?\nA: Yes. Claims can exceed premium revenue; the tariff is not empirically calibrated.','Q: Does the marketplace stop every possible NFT transfer?\nA: No. Marketplace trading is restricted before departure; the report does not claim a global direct-transfer lock.','Q: Why is there still a refund transaction?\nA: Time alone does not execute contract code. Someone must trigger expiry after the grace window.','Q: Has Sepolia deployment been completed?\nA: No verified deployment or explorer links are currently evidenced.','Q: Is Slither clean?\nA: No. Eleven findings were retained and reviewed; passing tests are not an audit.']
(OUT/'Presentation_Script_EN.md').write_text('\n\n'.join(notes),encoding='utf-8')
assert sum(s[3] for s in slides)==720
